client_script:
frappe.web_form.after_load = () => {
	// fbq('track', 'ViewContent');
}

frappe.web_form.validate = () => {
    const field_name = "phone_number"; 
    const phone_value = frappe.web_form.get_value(field_name);

    if (phone_value) {
        // 1. Remove all non-digit characters (spaces, +, -, etc.)
        const digitsOnly = phone_value.replace(/[^\d]/g, '');

        // 2. Check if the remaining digit count is at least 10
        if (digitsOnly.length < 10) {
            frappe.msgprint({
                title: __('Invalid Phone Number'),
                message: __('Please enter a valid phone number with at least 10 digits.'),
                indicator: 'orange'
            });

            // Returning false stops the form from being submitted
            return false; 
        }

        const requirement = frappe.web_form.get_value('requirement');
        if (requirement == "Elder Assist") {
            // track Meta Pixel event for EA, before submitting
            fbq('track', 'EALead');
        }
    }
    
    return true; // Allow submission
};

custom_css:
/* Make the form look like a floating card */
.web-form-container {
    background-color: #ffffff;
    padding: 20px;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    margin-top: 30px;
}

.web-form-banner-image {
  object-fit: contain !important;  /* crop nicely without distortion */
  margin: -1rem 0rem -5rem !important;    /* remove negative margins */
  display: block;       /* ensures no inline spacing issues */
  max-height: 150px !important;
}

.btn-primary:hover {
    transform: translateY(-1px);
}

/* Add a nice border to inputs on focus */
.form-control:focus {
    border-color: #2490ef;
    box-shadow: 0 0 0 0.2rem rgba(36, 144, 239, 0.25);
}
